-- M3A Ticketing database bootstrap.
-- Hard-coded credentials are for local development only.
--
--     psql -h localhost -U postgres -f db/init.sql
--
-- (or mount this directory at /docker-entrypoint-initdb.d in the postgres image).
--
-- The tables mirror the EF Core model in src/M3A.Repositories/Persistence exactly
-- (`dotnet ef dbcontext script`): lower-case table names, quoted PascalCase columns,
-- string ids generated by the app (ResourceId.New), ticket status stored as text.
-- Change the model and this file together.
--
-- Roles:
--   m3a_admin — owns the schema objects (DDL).
--   m3a_svc   — what the API connects as (DB_USERNAME); data access only.
\set ON_ERROR_STOP on

CREATE USER m3a_svc WITH PASSWORD 'password';
CREATE USER m3a_admin WITH PASSWORD 'password';

CREATE DATABASE m3a_db;

\connect m3a_db

GRANT ALL PRIVILEGES ON DATABASE m3a_db TO m3a_admin;
GRANT CONNECT ON DATABASE m3a_db TO m3a_svc;
GRANT USAGE ON SCHEMA public TO m3a_admin;
GRANT USAGE ON SCHEMA public TO m3a_svc;
GRANT CREATE ON SCHEMA public TO m3a_admin;

\connect m3a_db m3a_admin

-- Tables m3a_admin creates later (new migrations, hand-run DDL) are usable by the
-- service without re-running the grants below.
ALTER DEFAULT PRIVILEGES IN SCHEMA public
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO m3a_svc;

CREATE TABLE venues (
    "Id"       VARCHAR(64)  NOT NULL,
    "Location" VARCHAR(256) NOT NULL,
    "Capacity" INTEGER      NOT NULL,
    CONSTRAINT "PK_venues" PRIMARY KEY ("Id")
);

CREATE TABLE events (
    "Id"            VARCHAR(64)              NOT NULL,
    "Name"          VARCHAR(256)             NOT NULL,
    "DateTime"      TIMESTAMP WITH TIME ZONE NOT NULL,
    "EventCapacity" INTEGER                  NOT NULL,
    "VenueId"       VARCHAR(64)              NOT NULL,
    CONSTRAINT "PK_events" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_events_venues_VenueId" FOREIGN KEY ("VenueId")
        REFERENCES venues ("Id") ON DELETE RESTRICT
);
CREATE INDEX "IX_events_VenueId" ON events ("VenueId");

CREATE TABLE tickets (
    "Id"      VARCHAR(64) NOT NULL,
    "EventId" VARCHAR(64) NOT NULL,
    "Status"  VARCHAR(32) NOT NULL, -- Issued | Purchased | Redeemed (TicketStatus as string)
    CONSTRAINT "PK_tickets" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_tickets_events_EventId" FOREIGN KEY ("EventId")
        REFERENCES events ("Id") ON DELETE RESTRICT
);
CREATE INDEX "IX_tickets_EventId" ON tickets ("EventId");

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO m3a_svc;
